const workerOrigin='cloudflare-worker-paypal-subscriptions';
const tiers={supporter:{label:'Supporter',price:'3.00',runtimeTier:'supporter_3'},intelligence:{label:'Intelligence Member',price:'6.00',runtimeTier:'intelligence_6'},research_pro:{label:'Research Pro',price:'9.00',runtimeTier:'research_pro_9'}};
const exactRoutes=new Set(['/api/paypal/config','/api/paypal/checkout-intent','/api/paypal/subscription/create','/api/paypal/subscription/return','/api/paypal/subscription/confirm','/api/paypal/subscription','/api/paypal/subscription/cancel','/api/paypal/donation/config','/api/paypal/donation/order','/api/paypal/donation/capture','/api/paypal/webhook','/api/paypal/admin/health','/api/paypal/admin/plans/bootstrap','/api/paypal/admin/subscriptions','/api/paypal/admin/events','/api/paypal/admin/reconcile','/api/paypal/admin/activation']);
export const paypalRoutes=exactRoutes;
export function isPayPalRoute(pathname=''){return exactRoutes.has(pathname)}

const headers={'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff','X-Frame-Options':'SAMEORIGIN','Referrer-Policy':'strict-origin-when-cross-origin','X-Matrix-Origin':workerOrigin};
function json(data,status=200,extra={}){return new Response(JSON.stringify(data,null,2),{status,headers:{...headers,...extra}})}
function redirect(location){return new Response(null,{status:303,headers:{...headers,Location:location}})}
function clean(value,max=500){return String(value??'').replace(/[\u0000-\u001f\u007f]/g,' ').replace(/\s+/g,' ').trim().slice(0,max)}
function paypalCredential(value){let text=String(value??'').trim();if(text.length>=2&&((text.startsWith('\"')&&text.endsWith('\"'))||(text.startsWith("'")&&text.endsWith("'"))))text=text.slice(1,-1).trim();return text}
function now(){return new Date().toISOString()}
function id(prefix){return `${prefix}-${crypto.randomUUID()}`}
function hasD1(env){return Boolean(env?.MEMBERS_DB&&typeof env.MEMBERS_DB.prepare==='function')}
async function first(statement){try{return await statement.first()}catch{return null}}
async function all(statement){try{const result=await statement.all();return Array.isArray(result?.results)?result.results:[]}catch{return[]}}
async function body(request){try{return await request.json()}catch{return{}}}
function cookie(request,name='matrix_session'){const raw=request.headers.get('cookie')||'';for(const part of raw.split(';')){const index=part.indexOf('=');if(index>0&&part.slice(0,index).trim()===name)return decodeURIComponent(part.slice(index+1).trim())}return''}
async function hash(value){const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(String(value||'')));return Array.from(new Uint8Array(digest)).map(byte=>byte.toString(16).padStart(2,'0')).join('')}
function bool(value){return value===true||value===1||value==='1'||String(value||'').toLowerCase()==='true'}
function environment(env){return String(env?.PAYPAL_ENVIRONMENT||'sandbox').toLowerCase()==='live'?'live':'sandbox'}
function apiBase(env){return environment(env)==='live'?'https://api-m.paypal.com':'https://api-m.sandbox.paypal.com'}
function configured(env){return Boolean(paypalCredential(env?.PAYPAL_CLIENT_ID)&&paypalCredential(env?.PAYPAL_CLIENT_SECRET)&&paypalCredential(env?.PAYPAL_WEBHOOK_ID))}
function normalizedProviderStatus(value){return clean(value||'UNKNOWN',50).toUpperCase().replace(/[^A-Z_]/g,'_')}
function localState(providerStatus){const status=normalizedProviderStatus(providerStatus);if(status==='APPROVAL_PENDING')return'pending_approval';if(status==='APPROVED')return'approved';if(status==='ACTIVE')return'active';if(status==='SUSPENDED')return'suspended';if(status==='CANCELLED')return'cancelled';if(status==='EXPIRED')return'expired';return'unknown'}
function tierForPlanRow(row){return row&&tiers[row.tier]?row.tier:''}
function entitlementForState(state,failureCount=0,periodEnd=null){if(state==='active')return true;if(state==='past_due')return Number(failureCount||0)<2;if(state==='cancelled_period_end')return Boolean(periodEnd&&Date.parse(periodEnd)>Date.now());return false}
function deny(auth,required='registered',message='Access denied'){return json({ok:false,authenticated:Boolean(auth),error:message,requiredTier:required,currentTier:auth?.entitlement?.effective_tier||'anonymous',upgradeUrl:'/membership.html'},auth?403:401)}
function safePayload(value,max=200000){try{const text=JSON.stringify(value??{});return text.length<=max?text:JSON.stringify({truncated:true})}catch{return'{}'}}

async function auth(request,env){if(!hasD1(env))return null;const raw=cookie(request);if(!raw)return null;const sessionHash=await hash(raw);const session=await first(env.MEMBERS_DB.prepare('SELECT id,member_id,expires_at,revoked_at FROM member_sessions WHERE session_hash=? LIMIT 1').bind(sessionHash));if(!session||session.revoked_at||Date.parse(session.expires_at)<=Date.now())return null;const member=await first(env.MEMBERS_DB.prepare("SELECT id,email,display_name,role,status,email_verified_at FROM members WHERE id=? AND status='active' LIMIT 1").bind(session.member_id));if(!member)return null;const entitlement=await first(env.MEMBERS_DB.prepare('SELECT effective_tier,tier_rank,is_admin,paid_access FROM member_effective_entitlements WHERE member_id=? LIMIT 1').bind(member.id))||{effective_tier:'registered',tier_rank:1,is_admin:member.role==='admin'?1:0,paid_access:0};return{session,member,entitlement:{...entitlement,tier_rank:Number(entitlement.tier_rank||0),is_admin:Boolean(entitlement.is_admin),paid_access:Boolean(entitlement.paid_access)}}}
async function requireAuth(request,env){const value=await auth(request,env);return value?{auth:value}:{response:deny(null)}}
async function requireAdmin(request,env){const required=await requireAuth(request,env);if(required.response)return required;if(!required.auth.entitlement.is_admin)return{response:deny(required.auth,'admin','Administrator access required')};return required}
async function audit(env,actorId,action,targetType,targetId,metadata={}){await env.MEMBERS_DB.prepare('INSERT INTO audit_log (id,actor_id,action,target_type,target_id,metadata_json,created_at) VALUES (?,?,?,?,?,?,?)').bind(id('audit'),actorId||null,action,targetType||null,targetId||null,safePayload(metadata,12000),now()).run().catch(()=>null)}

async function accessToken(env){const clientId=paypalCredential(env?.PAYPAL_CLIENT_ID);const clientSecret=paypalCredential(env?.PAYPAL_CLIENT_SECRET);const webhookId=paypalCredential(env?.PAYPAL_WEBHOOK_ID);if(!clientId||!clientSecret||!webhookId)throw new Error('PayPal credentials and webhook ID are not configured');const oauthCredential=btoa(`${clientId}:${clientSecret}`);const response=await fetch(`${apiBase(env)}/v1/oauth2/token`,{method:'POST',headers:{Authorization:`Basic ${oauthCredential}`,'Content-Type':'application/x-www-form-urlencoded',Accept:'application/json'},body:'grant_type=client_credentials'});const text=await response.text();let payload={};try{payload=JSON.parse(text||'{}')}catch{}if(!response.ok||!payload.access_token)throw new Error(clean(payload.error_description||payload.message||text||'PayPal OAuth failed',700));return payload.access_token}
async function paypal(env,pathname,options={}){const token=await accessToken(env);const response=await fetch(`${apiBase(env)}${pathname}`,{...options,headers:{Authorization:`Bearer ${token}`,Accept:'application/json','Content-Type':'application/json','PayPal-Request-Id':options.requestId||id('request'),...(options.headers||{})}});const text=await response.text();let payload={};if(text){try{payload=JSON.parse(text)}catch{payload={raw:text}}}if(!response.ok){const details=Array.isArray(payload.details)?payload.details.map(item=>clean(`${item.issue||''}${item.description?`: ${item.description}`:''}`,500)).filter(Boolean).join('; '):'';const failure=new Error(clean(details||payload.message||payload.error_description||payload.name||text||`PayPal HTTP ${response.status}`,900));failure.paypalDebugId=clean(payload.debug_id||'',120);failure.paypalName=clean(payload.name||'',120);throw failure}return{status:response.status,payload}}
async function subscriptionDetails(env,subscriptionId){return(await paypal(env,`/v1/billing/subscriptions/${encodeURIComponent(clean(subscriptionId,140))}`,{method:'GET'})).payload}

async function runtimeSetting(env,targetEnvironment){return await first(env.MEMBERS_DB.prepare('SELECT environment,checkout_enabled,activation_reason,activated_by,activated_at,deactivated_at,updated_at FROM paypal_runtime_settings WHERE environment=? LIMIT 1').bind(targetEnvironment))||{environment:targetEnvironment,checkout_enabled:0}}
async function plans(env,targetEnvironment=environment(env)){return await all(env.MEMBERS_DB.prepare("SELECT tier,provider_product_id,provider_plan_id,amount_value,currency_code,status FROM paypal_plans WHERE environment=? AND status='ACTIVE' ORDER BY CASE tier WHEN 'supporter' THEN 1 WHEN 'intelligence' THEN 2 ELSE 3 END").bind(targetEnvironment))}
async function activationState(env){const target=environment(env);const setting=await runtimeSetting(env,target);const environmentSwitch=target==='live'?bool(env?.PAYPAL_PRODUCTION_ENABLED):bool(env?.PAYPAL_SANDBOX_ENABLED);const confirmation=target!=='live'||String(env?.PAYPAL_LIVE_ACTIVATION_CONFIRMATION||'')==='MATRIX_PAYPAL_LIVE_CONFIRMED';const planRows=await plans(env,target);const plansReady=planRows.length===3&&planRows.every(row=>String(row.status).toUpperCase()==='ACTIVE'&&row.provider_plan_id&&row.provider_product_id);return{environment:target,configured:configured(env),environmentSwitch,databaseSwitch:Boolean(setting.checkout_enabled),confirmation,plansReady,checkoutEnabled:configured(env)&&environmentSwitch&&Boolean(setting.checkout_enabled)&&confirmation&&plansReady,setting,plans:planRows}}


function donationAmount(value){const parsed=Number(String(value??'').replace(',','.'));if(!Number.isFinite(parsed)||parsed<1||parsed>500000000)return null;return parsed.toFixed(2)}
async function donationState(env){const target=environment(env);const environmentSwitch=target==='live'?bool(env?.PAYPAL_PRODUCTION_ENABLED):bool(env?.PAYPAL_SANDBOX_ENABLED);const confirmation=target!=='live'||String(env?.PAYPAL_LIVE_ACTIVATION_CONFIRMATION||'')==='MATRIX_PAYPAL_LIVE_CONFIRMED';const enabled=bool(env?.PAYPAL_DONATIONS_ENABLED)&&configured(env)&&environmentSwitch&&confirmation;return{environment:target,configured:configured(env),environmentSwitch,confirmation,donationsSwitch:bool(env?.PAYPAL_DONATIONS_ENABLED),enabled,liveChargingEnabled:target==='live'&&enabled,minAmount:'1.00',maxAmount:'5000.00',currency:'EUR'}}
async function donationConfig(request,env){const state=await donationState(env);return json({ok:true,...state,publicEvidenceFree:true,requiresMemberLogin:true,legalBoundary:'This is a voluntary support payment, not a charitable or tax-deductible donation. It does not buy stronger evidence, alter conclusions or restrict the public evidence routes.'})}
async function createDonationOrder(request,env){const required=await requireAuth(request,env);if(required.response)return required.response;const state=await donationState(env);if(!state.enabled)return json({ok:false,error:'Voluntary PayPal support is disabled until the configured sandbox or live safety gates pass',environment:state.environment,liveChargingEnabled:false},503);const input=await body(request);const amount=donationAmount(input.amount);if(!amount)return json({ok:false,error:'Choose a donation amount between €1.00 and €5,000.00'},400);const productKey=clean(input.productKey||'matrix-reprogrammed-support',80).replace(/[^a-z0-9_-]/gi,'-');const label=clean(input.label||'Matrix Reprogrammed public-record research',120);const customId=clean(`${required.auth.member.id}:${productKey}`,127);const origin=new URL(request.url).origin;const result=await paypal(env,'/v2/checkout/orders',{method:'POST',requestId:id('donation-order'),body:JSON.stringify({intent:'CAPTURE',purchase_units:[{reference_id:productKey,custom_id:customId,description:label,amount:{currency_code:'EUR',value:amount}}],application_context:{brand_name:'Matrix Reprogrammed',landing_page:'NO_PREFERENCE',user_action:'PAY_NOW',return_url:`${origin}/store.html?donation=approved`,cancel_url:`${origin}/store.html?donation=cancelled`}})});const order=result.payload||{};const approveUrl=(order.links||[]).find(link=>link.rel==='approve')?.href||'';if(!order.id||!approveUrl)throw new Error('PayPal did not return an approval link');await audit(env,required.auth.member.id,'paypal.donation.order_created','paypal_order',order.id,{amount,currency:'EUR',productKey,label,environment:state.environment});return json({ok:true,orderId:order.id,approveUrl,amount,currency:'EUR',environment:state.environment,liveChargingEnabled:state.liveChargingEnabled})}
async function captureDonationOrder(request,env){const required=await requireAuth(request,env);if(required.response)return required.response;const state=await donationState(env);if(!state.enabled)return json({ok:false,error:'Voluntary PayPal support is disabled until the configured sandbox or live safety gates pass',environment:state.environment,liveChargingEnabled:false},503);const input=await body(request);const orderId=clean(input.orderId,140);if(!/^[A-Z0-9-]{8,140}$/i.test(orderId))return json({ok:false,error:'A valid PayPal order ID is required'},400);const result=await paypal(env,`/v2/checkout/orders/${encodeURIComponent(orderId)}/capture`,{method:'POST',requestId:`matrix-donation-capture-${orderId}`});const payload=result.payload||{};const unit=payload.purchase_units?.[0]||{};const capture=unit.payments?.captures?.[0]||{};const customId=clean(unit.custom_id,127);if(!customId.startsWith(`${required.auth.member.id}:`))return json({ok:false,error:'PayPal support order does not belong to this member'},409);const amount=donationAmount(capture.amount?.value||unit.amount?.value);const currency=clean(capture.amount?.currency_code||unit.amount?.currency_code||'',10).toUpperCase();if(payload.status!=='COMPLETED'||capture.status!=='COMPLETED'||!amount||currency!=='EUR')return json({ok:false,error:'PayPal support payment is not complete or has an invalid amount'},409);const paymentId=clean(capture.id||orderId,160);const eventId=`donation:${orderId}`;const current=now();await env.MEMBERS_DB.prepare('INSERT OR IGNORE INTO paypal_payment_records (id,subscription_id,provider_subscription_id,provider_payment_id,provider_event_id,payment_type,status,gross_amount,refund_amount,currency_code,paid_at,refunded_at,reversed_at,raw_resource_json,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(id('payment'),null,null,paymentId,eventId,'donation','COMPLETED',amount,null,'EUR',clean(capture.create_time||current,100),null,null,safePayload(payload),current,current).run();await audit(env,required.auth.member.id,'paypal.donation.captured','paypal_payment',paymentId,{orderId,amount,currency:'EUR',productKey:clean(unit.reference_id,80),environment:state.environment});return json({ok:true,completed:true,orderId,paymentId,amount,currency:'EUR',environment:state.environment,liveChargingEnabled:state.liveChargingEnabled,message:'Thank you for supporting the public-record research archive.'})}

async function bootstrapPlans(request,env){const required=await requireAdmin(request,env);if(required.response)return required.response;if(!configured(env))return json({ok:false,error:'PayPal credentials and webhook ID are required'},503);const target=environment(env);const current=now();const results=[];for(const [tier,definition] of Object.entries(tiers)){let product=await first(env.MEMBERS_DB.prepare('SELECT * FROM paypal_products WHERE environment=? AND tier=? LIMIT 1').bind(target,tier));if(!product){const created=(await paypal(env,'/v1/catalogs/products',{method:'POST',requestId:`matrix-product-${target}-${tier}`,body:JSON.stringify({name:`Matrix Reprogrammed ${definition.label}`,description:`Monthly ${definition.label} membership`,type:'SERVICE',category:'SOFTWARE'})})).payload;product={id:id('paypal-product'),provider_product_id:created.id,name:created.name||definition.label,description:created.description||'',status:'active'};await env.MEMBERS_DB.prepare('INSERT INTO paypal_products (id,environment,tier,provider_product_id,name,description,status,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?)').bind(product.id,target,tier,product.provider_product_id,product.name,product.description,'active',current,current).run()}
    let plan=await first(env.MEMBERS_DB.prepare('SELECT * FROM paypal_plans WHERE environment=? AND tier=? LIMIT 1').bind(target,tier));if(!plan){const created=(await paypal(env,'/v1/billing/plans',{method:'POST',requestId:`matrix-plan-${target}-${tier}`,body:JSON.stringify({product_id:product.provider_product_id,name:`Matrix Reprogrammed ${definition.label}`,description:`${definition.label} monthly membership`,status:'ACTIVE',billing_cycles:[{frequency:{interval_unit:'MONTH',interval_count:1},tenure_type:'REGULAR',sequence:1,total_cycles:0,pricing_scheme:{fixed_price:{value:definition.price,currency_code:'EUR'}}}],payment_preferences:{auto_bill_outstanding:true,setup_fee:{value:'0.00',currency_code:'EUR'},setup_fee_failure_action:'CONTINUE',payment_failure_threshold:2}})})).payload;plan={id:id('paypal-plan'),provider_plan_id:created.id,status:created.status||'ACTIVE'};await env.MEMBERS_DB.prepare('INSERT INTO paypal_plans (id,environment,tier,provider_product_id,provider_plan_id,amount_value,currency_code,interval_unit,interval_count,status,payment_failure_threshold,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(plan.id,target,tier,product.provider_product_id,plan.provider_plan_id,definition.price,'EUR','MONTH',1,String(plan.status).toUpperCase(),2,current,current).run()}
    results.push({tier,productId:product.provider_product_id,planId:plan.provider_plan_id,amount:definition.price,status:plan.status})}
  await audit(env,required.auth.member.id,'paypal.plans.bootstrapped','paypal_environment',target,{results});return json({ok:true,environment:target,plans:results,checkoutEnabled:(await activationState(env)).checkoutEnabled})}

async function config(request,env){const required=await requireAuth(request,env);if(required.response)return required.response;const state=await activationState(env);return json({ok:true,authenticated:true,environment:state.environment,currency:'EUR',clientId:state.configured?String(env.PAYPAL_CLIENT_ID):null,configured:state.configured,checkoutEnabled:state.checkoutEnabled,webhookConfigured:Boolean(env.PAYPAL_WEBHOOK_ID),tiers:Object.fromEntries(Object.entries(tiers).map(([key,value])=>[key,{label:value.label,price:value.price,planId:state.plans.find(plan=>plan.tier===key)?.provider_plan_id||null}])),activation:{environmentSwitch:state.environmentSwitch,databaseSwitch:state.databaseSwitch,confirmation:state.confirmation,plansReady:state.plansReady}})}
async function checkoutIntent(request,env){const required=await requireAuth(request,env);if(required.response)return required.response;const state=await activationState(env);if(!state.checkoutEnabled)return json({ok:false,configured:state.configured,environment:state.environment,error:'PayPal checkout is disabled until activation gates pass'},503);const input=await body(request);const tier=clean(input.tier,40);if(!tiers[tier])return json({ok:false,error:'Unknown membership tier'},400);const plan=state.plans.find(item=>item.tier===tier);if(!plan)return json({ok:false,error:'The selected PayPal plan is unavailable'},409);const current=new Date();const expiresAt=new Date(current.getTime()+30*60*1000).toISOString();await env.MEMBERS_DB.prepare('UPDATE paypal_checkout_intents SET used_at=? WHERE member_id=? AND used_at IS NULL').bind(current.toISOString(),required.auth.member.id).run();const intentId=id('paypal-intent');await env.MEMBERS_DB.prepare('INSERT INTO paypal_checkout_intents (id,member_id,tier,plan_id,expires_at,created_at) VALUES (?,?,?,?,?,?)').bind(intentId,required.auth.member.id,tier,plan.provider_plan_id,expiresAt,current.toISOString()).run();await env.MEMBERS_DB.prepare("INSERT INTO paypal_checkout_intent_state (checkout_intent_id,environment,status,updated_at,created_at) VALUES (?,?,'created',?,?)").bind(intentId,state.environment,current.toISOString(),current.toISOString()).run();return json({ok:true,intentId,tier,planId:plan.provider_plan_id,customId:intentId,clientId:String(env.PAYPAL_CLIENT_ID),currency:'EUR',environment:state.environment,expiresAt})}

async function createSubscriptionApproval(request,env){const intentResponse=await checkoutIntent(request,env);if(!intentResponse.ok)return intentResponse;const intent=await intentResponse.json();const origin=new URL(request.url).origin;const returnUrl=`${origin}/api/paypal/subscription/return?checkout_intent=${encodeURIComponent(intent.intentId)}`;const cancelUrl=`${origin}/membership.html?paypal=cancelled`;try{const result=await paypal(env,'/v1/billing/subscriptions',{method:'POST',requestId:`matrix-subscription-${intent.intentId}`,body:JSON.stringify({plan_id:intent.planId,custom_id:intent.intentId,application_context:{brand_name:'Matrix Reprogrammed',shipping_preference:'NO_SHIPPING',user_action:'SUBSCRIBE_NOW',return_url:returnUrl,cancel_url:cancelUrl}})});const created=result.payload||{};const approveUrl=(created.links||[]).find(link=>link.rel==='approve')?.href||'';if(!created.id||!approveUrl)throw new Error('PayPal did not return a subscription approval link');const current=now();await env.MEMBERS_DB.prepare("UPDATE paypal_checkout_intent_state SET status='created',provider_subscription_id=?,updated_at=? WHERE checkout_intent_id=?").bind(clean(created.id,140),current,intent.intentId).run().catch(()=>null);await audit(env,intent.memberId||null,'paypal.subscription.approval_created','paypal_subscription',created.id,{checkoutIntentId:intent.intentId,tier:intent.tier,environment:intent.environment});return json({ok:true,checkoutIntentId:intent.intentId,subscriptionId:created.id,approveUrl,environment:intent.environment,expiresAt:intent.expiresAt})}catch(error){const providerMessage=clean(error.message||error,700);const errorCode=clean(error.paypalName||'PAYPAL_SUBSCRIPTION_CREATE_FAILED',120);const debugId=clean(error.paypalDebugId||'',120)||null;await env.MEMBERS_DB.prepare("UPDATE paypal_checkout_intent_state SET status='failed',failed_at=?,failure_reason=?,updated_at=? WHERE checkout_intent_id=?").bind(now(),providerMessage,now(),intent.intentId).run().catch(()=>null);await audit(env,intent.memberId||null,'paypal.subscription.create_failed','paypal_checkout_intent',intent.intentId,{tier:intent.tier,environment:intent.environment,errorCode,debugId,message:providerMessage});return json({ok:false,error:'PayPal could not start the subscription.',message:providerMessage,errorCode,debugId,environment:intent.environment},502)}}
async function subscriptionReturn(request,env){const url=new URL(request.url);const checkoutIntentId=clean(url.searchParams.get('checkout_intent'),180);let subscriptionId=clean(url.searchParams.get('subscription_id')||url.searchParams.get('subscriptionId'),140);if(!checkoutIntentId)return redirect('/membership.html?paypal_error=missing_checkout_intent');if(!subscriptionId){const state=await first(env.MEMBERS_DB.prepare('SELECT provider_subscription_id FROM paypal_checkout_intent_state WHERE checkout_intent_id=? LIMIT 1').bind(checkoutIntentId));subscriptionId=clean(state?.provider_subscription_id,140)}if(!subscriptionId)return redirect('/membership.html?paypal_error=missing_subscription_id');const forwardedHeaders=new Headers({'content-type':'application/json'});const sessionCookie=request.headers.get('cookie');if(sessionCookie)forwardedHeaders.set('cookie',sessionCookie);const confirmation=await confirm(new Request(request.url,{method:'POST',headers:forwardedHeaders,body:JSON.stringify({subscriptionId,checkoutIntentId})}),env);let payload={};try{payload=await confirmation.clone().json()}catch{}if(!confirmation.ok)return redirect(`/membership.html?paypal_error=${encodeURIComponent(clean(payload.message||payload.error||'verification_failed',200))}`);return redirect('/billing-dashboard.html?paypal=confirmed')}
function billingTimes(details){const billing=details?.billing_info||{};return{nextBillingAt:clean(billing.next_billing_time||'',100)||null,lastPaymentAt:clean(billing.last_payment?.time||'',100)||null,lastPaymentId:clean(billing.last_payment?.amount?details.id:'',140)||null,lastPaymentAmount:clean(billing.last_payment?.amount?.value||'',40)||null,currencyCode:clean(billing.last_payment?.amount?.currency_code||'EUR',10)}}
async function subscriptionRow(env,providerSubscriptionId){return await first(env.MEMBERS_DB.prepare('SELECT * FROM subscriptions WHERE provider_subscription_id=? LIMIT 1').bind(providerSubscriptionId))}
async function recordTransition(env,{subscriptionId,providerSubscriptionId,eventId,eventType,fromState,toState,entitlementBefore,entitlementAfter,reason,payloadHash}){await env.MEMBERS_DB.prepare('INSERT OR IGNORE INTO paypal_subscription_transitions (id,subscription_id,provider_subscription_id,provider_event_id,event_type,from_state,to_state,entitlement_before,entitlement_after,reason,payload_hash,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)').bind(id('transition'),subscriptionId||null,providerSubscriptionId,eventId||null,eventType,fromState||null,toState,entitlementBefore?1:0,entitlementAfter?1:0,reason||'',payloadHash||null,now()).run()}
async function syncSubscription(env,details,memberId,event={}){const providerSubscriptionId=clean(details?.id,140);const planId=clean(details?.plan_id,140);if(!providerSubscriptionId||!planId)throw new Error('PayPal subscription response is incomplete');const plan=await first(env.MEMBERS_DB.prepare('SELECT tier FROM paypal_plans WHERE environment=? AND provider_plan_id=? LIMIT 1').bind(environment(env),planId));const tier=tierForPlanRow(plan);if(!tier)throw new Error('PayPal subscription does not match a configured plan');let row=await subscriptionRow(env,providerSubscriptionId);if(row&&row.member_id!==memberId)throw new Error('PayPal subscription is already attached to another member');const current=now();const providerStatus=normalizedProviderStatus(details.status);const times=billingTimes(details);if(!row){row={id:id('subscription')};await env.MEMBERS_DB.prepare('INSERT INTO subscriptions (id,member_id,provider,provider_customer_id,provider_subscription_id,provider_plan_id,tier,status,last_payment_at,next_billing_at,current_period_end,cancel_at_period_end,suspended_at,cancelled_at,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(row.id,memberId,'paypal',clean(details?.subscriber?.payer_id,140)||null,providerSubscriptionId,planId,tier,providerStatus,times.lastPaymentAt,times.nextBillingAt,times.nextBillingAt,0,null,null,current,current).run()}else await env.MEMBERS_DB.prepare('UPDATE subscriptions SET provider_customer_id=?,provider_plan_id=?,tier=?,status=?,last_payment_at=COALESCE(?,last_payment_at),next_billing_at=?,current_period_end=?,suspended_at=CASE WHEN ?=? THEN COALESCE(suspended_at,?) ELSE suspended_at END,cancelled_at=CASE WHEN ? IN (?,?) THEN COALESCE(cancelled_at,?) ELSE cancelled_at END,updated_at=? WHERE id=?').bind(clean(details?.subscriber?.payer_id,140)||null,planId,tier,providerStatus,times.lastPaymentAt,times.nextBillingAt,times.nextBillingAt,providerStatus,'SUSPENDED',current,providerStatus,'CANCELLED','EXPIRED',current,current,row.id).run();
  const old=await first(env.MEMBERS_DB.prepare('SELECT * FROM paypal_subscription_state WHERE subscription_id=? LIMIT 1').bind(row.id));let state=localState(providerStatus);let periodEnd=times.nextBillingAt||old?.current_period_end||null;if(providerStatus==='CANCELLED'&&periodEnd&&Date.parse(periodEnd)>Date.now())state='cancelled_period_end';const failures=state==='active'?0:Number(old?.payment_failure_count||0);const entitlement=entitlementForState(state,failures,periodEnd);await env.MEMBERS_DB.prepare('INSERT INTO paypal_subscription_state (subscription_id,provider_subscription_id,environment,billing_state,entitlement_active,payment_failure_count,refund_hold,reversal_hold,current_period_start,current_period_end,last_payment_id,last_payment_amount,currency_code,last_failed_payment_at,last_refund_at,last_reversal_at,last_event_id,last_event_type,last_event_at,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(subscription_id) DO UPDATE SET provider_subscription_id=excluded.provider_subscription_id,environment=excluded.environment,billing_state=excluded.billing_state,entitlement_active=excluded.entitlement_active,payment_failure_count=excluded.payment_failure_count,refund_hold=CASE WHEN excluded.billing_state=? THEN 0 ELSE paypal_subscription_state.refund_hold END,reversal_hold=CASE WHEN excluded.billing_state=? THEN 0 ELSE paypal_subscription_state.reversal_hold END,current_period_end=excluded.current_period_end,last_payment_id=COALESCE(excluded.last_payment_id,paypal_subscription_state.last_payment_id),last_payment_amount=COALESCE(excluded.last_payment_amount,paypal_subscription_state.last_payment_amount),currency_code=excluded.currency_code,last_event_id=excluded.last_event_id,last_event_type=excluded.last_event_type,last_event_at=excluded.last_event_at,updated_at=excluded.updated_at').bind(row.id,providerSubscriptionId,environment(env),state,entitlement?1:0,failures,old?.refund_hold||0,old?.reversal_hold||0,null,periodEnd,times.lastPaymentId,times.lastPaymentAmount,times.currencyCode,null,old?.last_refund_at||null,old?.last_reversal_at||null,event.id||null,event.type||'subscription.sync',event.at||current,old?.created_at||current,current,'active','active').run();await recordTransition(env,{subscriptionId:row.id,providerSubscriptionId,eventId:event.id,eventType:event.type||'subscription.sync',fromState:old?.billing_state,toState:state,entitlementBefore:Boolean(old?.entitlement_active),entitlementAfter:entitlement,reason:`Provider status ${providerStatus}`,payloadHash:event.payloadHash});return{subscriptionId:providerSubscriptionId,localSubscriptionId:row.id,tier,status:providerStatus,billingState:state,paidAccess:entitlement,currentPeriodEnd:periodEnd,nextBillingAt:times.nextBillingAt}}

async function confirm(request,env){const required=await requireAuth(request,env);if(required.response)return required.response;const input=await body(request);const subscriptionId=clean(input.subscriptionId,140);const intentId=clean(input.checkoutIntentId,180);if(!subscriptionId||!intentId)return json({ok:false,error:'Subscription ID and checkout intent are required'},400);const intent=await first(env.MEMBERS_DB.prepare('SELECT i.id,i.member_id,i.tier,i.plan_id,i.expires_at,i.used_at,s.environment,s.status FROM paypal_checkout_intents i JOIN paypal_checkout_intent_state s ON s.checkout_intent_id=i.id WHERE i.id=? LIMIT 1').bind(intentId));if(!intent||intent.member_id!==required.auth.member.id||intent.used_at||Date.parse(intent.expires_at)<=Date.now())return json({ok:false,error:'Checkout intent is invalid or expired'},400);const details=await subscriptionDetails(env,subscriptionId);if(clean(details.id,140)!==subscriptionId||clean(details.plan_id,140)!==intent.plan_id||clean(details.custom_id,180)!==intent.id)return json({ok:false,error:'PayPal subscription verification failed'},400);const providerStatus=normalizedProviderStatus(details.status);if(!['APPROVAL_PENDING','APPROVED','ACTIVE'].includes(providerStatus))return json({ok:false,error:'PayPal subscription is not approved'},409);const synced=await syncSubscription(env,details,required.auth.member.id,{type:'checkout.confirm',at:now()});const current=now();await env.MEMBERS_DB.prepare('UPDATE paypal_checkout_intents SET used_at=? WHERE id=?').bind(current,intent.id).run();await env.MEMBERS_DB.prepare('UPDATE paypal_checkout_intent_state SET status=?,provider_subscription_id=?,approved_at=COALESCE(approved_at,?),confirmed_at=?,updated_at=? WHERE checkout_intent_id=?').bind(synced.paidAccess?'confirmed':'approved',subscriptionId,current,current,current,intent.id).run();await audit(env,required.auth.member.id,'paypal.subscription.confirmed','subscription',subscriptionId,synced);return json({ok:true,verified:true,subscription:synced,message:synced.paidAccess?'PayPal membership is active.':'PayPal approved the subscription; access activates only when PayPal reports ACTIVE.'})}
async function currentStatus(request,env){const required=await requireAuth(request,env);if(required.response)return required.response;const row=await first(env.MEMBERS_DB.prepare('SELECT * FROM paypal_current_subscription_status WHERE member_id=? ORDER BY state_updated_at DESC LIMIT 1').bind(required.auth.member.id));return json({ok:true,environment:environment(env),subscription:row||null,paidAccess:Boolean(row?.entitlement_active),effectiveTier:required.auth.entitlement.effective_tier})}
async function cancel(request,env){const required=await requireAuth(request,env);if(required.response)return required.response;const row=await first(env.MEMBERS_DB.prepare('SELECT * FROM paypal_current_subscription_status WHERE member_id=? ORDER BY state_updated_at DESC LIMIT 1').bind(required.auth.member.id));if(!row?.provider_subscription_id)return json({ok:false,error:'No PayPal subscription found'},404);if(['cancelled','expired'].includes(row.billing_state))return json({ok:true,alreadyCancelled:true,subscription:row});await paypal(env,`/v1/billing/subscriptions/${encodeURIComponent(row.provider_subscription_id)}/cancel`,{method:'POST',body:JSON.stringify({reason:'Cancelled by member through Matrix Reprogrammed'})});const periodEnd=row.current_period_end&&Date.parse(row.current_period_end)>Date.now()?row.current_period_end:null;const state=periodEnd?'cancelled_period_end':'cancelled';const entitlement=entitlementForState(state,0,periodEnd);const current=now();await env.MEMBERS_DB.prepare("UPDATE subscriptions SET status='CANCELLED',cancel_at_period_end=?,cancelled_at=?,updated_at=? WHERE id=?").bind(periodEnd?1:0,current,current,row.subscription_id).run();await env.MEMBERS_DB.prepare("UPDATE paypal_subscription_state SET billing_state=?,entitlement_active=?,current_period_end=?,last_event_type='member.cancel',last_event_at=?,updated_at=? WHERE subscription_id=?").bind(state,entitlement?1:0,periodEnd,current,current,row.subscription_id).run();await recordTransition(env,{subscriptionId:row.subscription_id,providerSubscriptionId:row.provider_subscription_id,eventType:'member.cancel',fromState:row.billing_state,toState:state,entitlementBefore:Boolean(row.entitlement_active),entitlementAfter:entitlement,reason:periodEnd?'Member cancelled; verified paid period retained':'Member cancelled; no future paid period established'});await audit(env,required.auth.member.id,'paypal.subscription.cancelled','subscription',row.provider_subscription_id,{state,periodEnd});return json({ok:true,cancelled:true,billingState:state,paidAccess:entitlement,currentPeriodEnd:periodEnd})}

function webhookHeaders(request){return{auth_algo:request.headers.get('paypal-auth-algo')||'',cert_url:request.headers.get('paypal-cert-url')||'',transmission_id:request.headers.get('paypal-transmission-id')||'',transmission_sig:request.headers.get('paypal-transmission-sig')||'',transmission_time:request.headers.get('paypal-transmission-time')||''}}
async function verifyWebhook(request,env,event,payloadHash){const h=webhookHeaders(request);const complete=h.auth_algo&&h.cert_url&&h.transmission_id&&h.transmission_sig&&h.transmission_time&&env?.PAYPAL_WEBHOOK_ID;if(!complete)return{ok:false,status:'FAILURE',headers:h,error:'Required PayPal transmission headers are missing'};try{const result=await paypal(env,'/v1/notifications/verify-webhook-signature',{method:'POST',body:JSON.stringify({...h,webhook_id:String(env.PAYPAL_WEBHOOK_ID),webhook_event:event})});const status=String(result.payload?.verification_status||'FAILURE').toUpperCase();return{ok:status==='SUCCESS',status,headers:h,error:status==='SUCCESS'?null:'PayPal returned non-success verification'}}catch(error){return{ok:false,status:'ERROR',headers:h,error:clean(error.message||error,700)}}}
function subscriptionIdFromEvent(event){const resource=event?.resource||{};if(String(event?.event_type||'').startsWith('BILLING.SUBSCRIPTION.'))return clean(resource.id,140);return clean(resource.billing_agreement_id||resource.supplementary_data?.related_ids?.subscription_id||resource.supplementary_data?.related_ids?.billing_agreement_id||'',140)}
async function recordPayment(env,event,subscription){const resource=event.resource||{};const type=String(event.event_type||'');let paymentType='sale';if(type.includes('REFUND'))paymentType='refund';else if(type.includes('REVERSED'))paymentType='reversal';else if(type.includes('PAYMENT.FAILED'))paymentType='failed_payment';else if(type.includes('CAPTURE'))paymentType='capture';const amount=resource.amount||resource.amount_with_breakdown?.gross_amount||resource.seller_receivable_breakdown?.gross_amount||{};await env.MEMBERS_DB.prepare('INSERT OR IGNORE INTO paypal_payment_records (id,subscription_id,provider_subscription_id,provider_payment_id,provider_event_id,payment_type,status,gross_amount,refund_amount,currency_code,paid_at,refunded_at,reversed_at,raw_resource_json,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(id('payment'),subscription?.id||null,subscription?.provider_subscription_id||subscriptionIdFromEvent(event)||null,clean(resource.id||event.id,160),event.id,paymentType,clean(resource.state||resource.status||type,80),paymentType==='sale'||paymentType==='capture'?clean(amount.total||amount.value||'',40)||null:null,paymentType==='refund'?clean(amount.total||amount.value||'',40)||null:null,clean(amount.currency||amount.currency_code||'EUR',10),paymentType==='sale'||paymentType==='capture'?clean(resource.create_time||event.create_time||now(),100):null,paymentType==='refund'?clean(resource.create_time||event.create_time||now(),100):null,paymentType==='reversal'?clean(resource.create_time||event.create_time||now(),100):null,safePayload(resource),now(),now()).run()}
async function processWebhookEvent(env,event,payloadHash){const eventType=clean(event.event_type,180);const eventAt=clean(event.create_time||now(),100);const providerSubscriptionId=subscriptionIdFromEvent(event);let subscription=providerSubscriptionId?await subscriptionRow(env,providerSubscriptionId):null;if(!subscription&&providerSubscriptionId){const customId=clean(event.resource?.custom_id,180);if(customId){const intent=await first(env.MEMBERS_DB.prepare('SELECT member_id FROM paypal_checkout_intents WHERE id=? LIMIT 1').bind(customId));if(intent){const details=await subscriptionDetails(env,providerSubscriptionId);await syncSubscription(env,details,intent.member_id,{id:event.id,type:eventType,at:eventAt,payloadHash});subscription=await subscriptionRow(env,providerSubscriptionId)}}}
  if(eventType.startsWith('BILLING.SUBSCRIPTION.')&&providerSubscriptionId&&subscription){const details=await subscriptionDetails(env,providerSubscriptionId);await syncSubscription(env,details,subscription.member_id,{id:event.id,type:eventType,at:eventAt,payloadHash});if(eventType==='BILLING.SUBSCRIPTION.PAYMENT.FAILED'){const current=await first(env.MEMBERS_DB.prepare('SELECT * FROM paypal_subscription_state WHERE subscription_id=? LIMIT 1').bind(subscription.id));const failures=Number(current?.payment_failure_count||0)+1;const state=failures>=2?'suspended':'past_due';const entitlement=entitlementForState(state,failures,current?.current_period_end);await env.MEMBERS_DB.prepare('UPDATE paypal_subscription_state SET billing_state=?,entitlement_active=?,payment_failure_count=?,last_failed_payment_at=?,last_event_id=?,last_event_type=?,last_event_at=?,updated_at=? WHERE subscription_id=?').bind(state,entitlement?1:0,failures,eventAt,event.id,eventType,eventAt,now(),subscription.id).run();await recordTransition(env,{subscriptionId:subscription.id,providerSubscriptionId,eventId:event.id,eventType,fromState:current?.billing_state,toState:state,entitlementBefore:Boolean(current?.entitlement_active),entitlementAfter:entitlement,reason:`Payment failure ${failures}`,payloadHash})}await recordPayment(env,event,subscription);return'processed'}
  if(['PAYMENT.SALE.COMPLETED'].includes(eventType)&&subscription){await recordPayment(env,event,subscription);const current=await first(env.MEMBERS_DB.prepare('SELECT * FROM paypal_subscription_state WHERE subscription_id=? LIMIT 1').bind(subscription.id));const resource=event.resource||{};const paidAt=clean(resource.create_time||eventAt,100);const nextEnd=clean(resource.billing_period?.end_time||current?.current_period_end||subscription.current_period_end||'',100)||null;await env.MEMBERS_DB.prepare("UPDATE subscriptions SET last_payment_at=?,current_period_end=COALESCE(?,current_period_end),updated_at=? WHERE id=?").bind(paidAt,nextEnd,now(),subscription.id).run();await env.MEMBERS_DB.prepare("UPDATE paypal_subscription_state SET billing_state='active',entitlement_active=1,payment_failure_count=0,refund_hold=0,reversal_hold=0,current_period_end=COALESCE(?,current_period_end),last_payment_id=?,last_payment_amount=?,currency_code=?,last_event_id=?,last_event_type=?,last_event_at=?,updated_at=? WHERE subscription_id=?").bind(nextEnd,clean(resource.id,160),clean(resource.amount?.total||resource.amount?.value||'',40)||null,clean(resource.amount?.currency||resource.amount?.currency_code||'EUR',10),event.id,eventType,eventAt,now(),subscription.id).run();await recordTransition(env,{subscriptionId:subscription.id,providerSubscriptionId,eventId:event.id,eventType,fromState:current?.billing_state,toState:'active',entitlementBefore:Boolean(current?.entitlement_active),entitlementAfter:true,reason:'Verified completed subscription payment',payloadHash});return'processed'}
  if((eventType.includes('REFUNDED')||eventType.includes('REVERSED'))&&subscription){await recordPayment(env,event,subscription);const current=await first(env.MEMBERS_DB.prepare('SELECT * FROM paypal_subscription_state WHERE subscription_id=? LIMIT 1').bind(subscription.id));const reversal=eventType.includes('REVERSED');const state=reversal?'reversal_hold':'refund_hold';await env.MEMBERS_DB.prepare(`UPDATE paypal_subscription_state SET billing_state=?,entitlement_active=0,${reversal?'reversal_hold=1,last_reversal_at=?':'refund_hold=1,last_refund_at=?'},last_event_id=?,last_event_type=?,last_event_at=?,updated_at=? WHERE subscription_id=?`).bind(state,eventAt,event.id,eventType,eventAt,now(),subscription.id).run();await recordTransition(env,{subscriptionId:subscription.id,providerSubscriptionId,eventId:event.id,eventType,fromState:current?.billing_state,toState:state,entitlementBefore:Boolean(current?.entitlement_active),entitlementAfter:false,reason:reversal?'Verified payment reversal':'Verified refund',payloadHash});return'processed'}
  await recordPayment(env,event,subscription);return providerSubscriptionId?'unmatched':'ignored'}
async function webhook(request,env){if(!hasD1(env)||!configured(env))return json({ok:false,error:'PayPal webhook processing is unavailable'},503);const raw=await request.text();const payloadHash=await hash(raw);let event;try{event=JSON.parse(raw)}catch{return json({ok:false,error:'Invalid PayPal webhook JSON'},400)}const eventId=clean(event.id,180);const eventType=clean(event.event_type,180);if(!eventId||!eventType)return json({ok:false,error:'PayPal event ID and type are required'},400);const verification=await verifyWebhook(request,env,event,payloadHash);const created=now();await env.MEMBERS_DB.prepare('INSERT OR REPLACE INTO paypal_webhook_verifications (provider_event_id,webhook_id,verification_method,verification_status,transmission_id,transmission_time,cert_url,auth_algo,payload_hash,verified_at,error_message,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)').bind(eventId,String(env.PAYPAL_WEBHOOK_ID), 'paypal_postback',verification.status,verification.headers.transmission_id||null,verification.headers.transmission_time||null,verification.headers.cert_url||null,verification.headers.auth_algo||null,payloadHash,verification.ok?created:null,verification.error||null,created).run();if(!verification.ok)return json({ok:false,error:'PayPal webhook signature verification failed'},400);const duplicate=await first(env.MEMBERS_DB.prepare('SELECT processing_status FROM payment_webhook_events WHERE provider_event_id=? LIMIT 1').bind(eventId));if(duplicate)return json({ok:true,verified:true,duplicate:true,eventId,processingStatus:duplicate.processing_status});await env.MEMBERS_DB.prepare('INSERT INTO payment_webhook_events (id,provider,provider_event_id,event_type,payload_json,received_at,processing_status) VALUES (?,?,?,?,?,?,?)').bind(id('webhook'),'paypal',eventId,eventType,raw,created,'pending').run();try{const processingStatus=await processWebhookEvent(env,event,payloadHash);await env.MEMBERS_DB.prepare('UPDATE payment_webhook_events SET processed_at=?,processing_status=? WHERE provider_event_id=?').bind(now(),processingStatus,eventId).run();return json({ok:true,verified:true,eventId,eventType,processingStatus})}catch(error){await env.MEMBERS_DB.prepare("UPDATE payment_webhook_events SET processed_at=?,processing_status='error',error_message=? WHERE provider_event_id=?").bind(now(),clean(error.message||error,900),eventId).run();return json({ok:false,verified:true,error:'PayPal webhook processing failed'},500)}}

async function health(request,env){const required=await requireAdmin(request,env);if(required.response)return required.response;const state=await activationState(env);const counts={subscriptions:Number((await first(env.MEMBERS_DB.prepare("SELECT COUNT(*) AS count FROM subscriptions WHERE provider='paypal'")))?.count||0),events:Number((await first(env.MEMBERS_DB.prepare('SELECT COUNT(*) AS count FROM payment_webhook_events')))?.count||0),transitions:Number((await first(env.MEMBERS_DB.prepare('SELECT COUNT(*) AS count FROM paypal_subscription_transitions')))?.count||0),payments:Number((await first(env.MEMBERS_DB.prepare('SELECT COUNT(*) AS count FROM paypal_payment_records')))?.count||0)};return json({ok:true,...state,counts,realChargesDuringCi:false})}
async function adminSubscriptions(request,env){const required=await requireAdmin(request,env);if(required.response)return required.response;const rows=await all(env.MEMBERS_DB.prepare('SELECT s.member_id,m.email,c.* FROM paypal_current_subscription_status c JOIN subscriptions s ON s.id=c.subscription_id JOIN members m ON m.id=s.member_id ORDER BY c.state_updated_at DESC LIMIT 500'));return json({ok:true,count:rows.length,subscriptions:rows})}
async function adminEvents(request,env){const required=await requireAdmin(request,env);if(required.response)return required.response;const events=await all(env.MEMBERS_DB.prepare('SELECT provider_event_id,event_type,received_at,processed_at,processing_status,error_message FROM payment_webhook_events ORDER BY received_at DESC LIMIT 500'));const transitions=await all(env.MEMBERS_DB.prepare('SELECT provider_subscription_id,provider_event_id,event_type,from_state,to_state,entitlement_before,entitlement_after,reason,created_at FROM paypal_subscription_transitions ORDER BY created_at DESC LIMIT 500'));return json({ok:true,events,transitions})}
async function reconcile(request,env){const required=await requireAdmin(request,env);if(required.response)return required.response;const input=await body(request);const scope=clean(input.scope||'all',100);const runId=id('reconcile');const started=now();await env.MEMBERS_DB.prepare("INSERT INTO paypal_reconciliation_runs (id,environment,scope,status,started_by,started_at) VALUES (?,?,?,'running',?,?)").bind(runId,environment(env),scope,required.auth.member.id,started).run();const rows=await all(env.MEMBERS_DB.prepare("SELECT * FROM subscriptions WHERE provider='paypal' ORDER BY updated_at DESC LIMIT 500"));let checked=0,changed=0,failed=0;const details=[];for(const row of rows){try{const before=await first(env.MEMBERS_DB.prepare('SELECT billing_state,entitlement_active FROM paypal_subscription_state WHERE subscription_id=? LIMIT 1').bind(row.id));const provider=await subscriptionDetails(env,row.provider_subscription_id);const synced=await syncSubscription(env,provider,row.member_id,{type:'admin.reconcile',at:now()});checked++;if(before?.billing_state!==synced.billingState||Boolean(before?.entitlement_active)!==Boolean(synced.paidAccess))changed++;details.push({subscriptionId:row.provider_subscription_id,ok:true,billingState:synced.billingState})}catch(error){checked++;failed++;details.push({subscriptionId:row.provider_subscription_id,ok:false,error:clean(error.message||error,400)})}}
  const status=failed===0?'completed':failed<checked?'partially_failed':'failed';await env.MEMBERS_DB.prepare('UPDATE paypal_reconciliation_runs SET status=?,checked_count=?,changed_count=?,failed_count=?,details_json=?,completed_at=? WHERE id=?').bind(status,checked,changed,failed,safePayload(details,100000),now(),runId).run();await audit(env,required.auth.member.id,'paypal.reconciliation.completed','paypal_reconciliation_run',runId,{status,checked,changed,failed});return json({ok:failed===0,runId,status,checked,changed,failed,details},failed===0?200:207)}
async function activation(request,env){const required=await requireAdmin(request,env);if(required.response)return required.response;const input=await body(request);const target=input.environment==='live'?'live':'sandbox';const enabled=Boolean(input.enabled);if(target!==environment(env))return json({ok:false,error:'Activation target must match PAYPAL_ENVIRONMENT'},409);const state=await activationState(env);if(enabled){if(!state.configured||!state.plansReady)return json({ok:false,error:'Credentials, webhook and all three active plans are required'},409);if(target==='sandbox'&&!bool(env.PAYPAL_SANDBOX_ENABLED))return json({ok:false,error:'PAYPAL_SANDBOX_ENABLED must be true'},409);if(target==='live'){if(!bool(env.PAYPAL_PRODUCTION_ENABLED)||String(env.PAYPAL_LIVE_ACTIVATION_CONFIRMATION||'')!=='MATRIX_PAYPAL_LIVE_CONFIRMED')return json({ok:false,error:'Live environment switches are not confirmed'},409);if(String(input.phrase||'')!=='ACTIVATE MATRIX PAYPAL LIVE')return json({ok:false,error:'Exact live activation phrase required'},400)}}const current=now();await env.MEMBERS_DB.prepare('UPDATE paypal_runtime_settings SET checkout_enabled=?,activation_reason=?,activated_by=?,activated_at=CASE WHEN ?=1 THEN ? ELSE activated_at END,deactivated_at=CASE WHEN ?=0 THEN ? ELSE deactivated_at END,updated_at=? WHERE environment=?').bind(enabled?1:0,clean(input.reason||`${enabled?'Enabled':'Disabled'} by administrator`,500),required.auth.member.id,enabled?1:0,current,enabled?1:0,current,current,target).run();await audit(env,required.auth.member.id,enabled?'paypal.activation.enabled':'paypal.activation.disabled','paypal_environment',target,{reason:input.reason||'',environmentSwitch:state.environmentSwitch});return json({ok:true,environment:target,checkoutEnabled:(await activationState(env)).checkoutEnabled})}

async function route(request,env){if(!hasD1(env))return json({ok:false,error:'Membership database unavailable'},503);const path=new URL(request.url).pathname.replace(/\/+$/,'')||'/';if(path==='/api/paypal/config'&&request.method==='GET')return config(request,env);if(path==='/api/paypal/checkout-intent'&&request.method==='POST')return checkoutIntent(request,env);if(path==='/api/paypal/subscription/create'&&request.method==='POST')return createSubscriptionApproval(request,env);if(path==='/api/paypal/subscription/return'&&request.method==='GET')return subscriptionReturn(request,env);if(path==='/api/paypal/subscription/confirm'&&request.method==='POST')return confirm(request,env);if(path==='/api/paypal/subscription'&&request.method==='GET')return currentStatus(request,env);if(path==='/api/paypal/subscription/cancel'&&request.method==='POST')return cancel(request,env);if(path==='/api/paypal/donation/config'&&request.method==='GET')return donationConfig(request,env);if(path==='/api/paypal/donation/order'&&request.method==='POST')return createDonationOrder(request,env);if(path==='/api/paypal/donation/capture'&&request.method==='POST')return captureDonationOrder(request,env);if(path==='/api/paypal/webhook'&&request.method==='POST')return webhook(request,env);if(path==='/api/paypal/admin/health'&&request.method==='GET')return health(request,env);if(path==='/api/paypal/admin/plans/bootstrap'&&request.method==='POST')return bootstrapPlans(request,env);if(path==='/api/paypal/admin/subscriptions'&&request.method==='GET')return adminSubscriptions(request,env);if(path==='/api/paypal/admin/events'&&request.method==='GET')return adminEvents(request,env);if(path==='/api/paypal/admin/reconcile'&&request.method==='POST')return reconcile(request,env);if(path==='/api/paypal/admin/activation'&&request.method==='POST')return activation(request,env);return json({ok:false,error:'PayPal route not found'},404)}
export default{async fetch(request,env){try{return await route(request,env)}catch(error){return json({ok:false,error:'PayPal service failed safely',message:clean(error.message||error,500)},500)}}};
